import { BrowserRouter, Routes, Route, NavLink, useNavigate } from 'react-router';

function Beranda() {
  return <h2>Beranda Toko Budi</h2>;
}

function Checkout() {
  const navigate = useNavigate();
  return (
    <div>
      <h2>Checkout</h2>
      <button onClick={() => navigate('/terima-kasih', { replace: true })}>Bayar</button>{' '}
      <button onClick={() => navigate(-1)}>Kembali</button>
    </div>
  );
}

function TerimaKasih() {
  return <h2>Terima kasih, pesananmu diproses!</h2>;
}

export default function App() {
  return (
    <BrowserRouter>
      <nav>
        <NavLink to="/">Beranda</NavLink> | <NavLink to="/checkout">Checkout</NavLink>
      </nav>
      <Routes>
        <Route path="/" element={<Beranda />} />
        <Route path="/checkout" element={<Checkout />} />
        <Route path="/terima-kasih" element={<TerimaKasih />} />
      </Routes>
    </BrowserRouter>
  );
}
